import math

class Shape:
    def area(self):
        return 0

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return math.pi * (self.radius ** 2)

def compute_total(shapes):
    total = 0
    for s in shapes:
        total += s.area()
    return total

r = Rectangle(3, 4)
c = Circle(2)
print(compute_total([r, c]))

